# Untrapped Ultra Mode - self-updating, self-healing system diagnostic
# Clean status output: only meaningful health/policy results receive a status label.
# Automatic changes remain limited to Untrapped-owned components.
$ErrorActionPreference='SilentlyContinue'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
$Parent=Split-Path -Parent $Root
$ReportPath=Join-Path $Root 'diagnostic-latest.txt'
$RepoBase='https://raw.githubusercontent.com/mehdishah5372-hue/Untrapped/main/'
$StatusPath=$MyInvocation.MyCommand.Path
$SelfRepairPath=Join-Path $Root 'self-repair.ps1'
$ExtensionFiles=@('manifest.json','background.js','content.js','popup.html','popup.js','bootstrap.bundle.min.js')
$CoreFiles=@('config.json','packet-filter.ps1','ultra-mode.ps1','status-untrapped.ps1','self-repair.ps1')
$Lines=New-Object 'System.Collections.Generic.List[string]'
$Problems=New-Object 'System.Collections.Generic.List[string]'
$Status=New-Object 'System.Collections.Generic.List[string]'
$RepairRan=$false;$UpdateState='UNKNOWN'
function Trace([string]$Stage,[string]$Message){$line='['+(Get-Date -Format 'HH:mm:ss')+'] ['+$Stage+'] '+$Message;Write-Host $line;[void]$Lines.Add($line)}
function Problem([string]$Message){if($Message -and -not($Problems -contains $Message)){[void]$Problems.Add($Message)}}
# Only important health/policy/result lines get a label. Inventory and descriptive facts stay plain.
function StatusLine([string]$Name,[string]$Value,[string]$State=''){if($State){$line=('{0}: {1} [{2}]' -f $Name,$Value,$State)}else{$line=('{0}: {1}' -f $Name,$Value)};[void]$Status.Add($line);Write-Host ('[STATUS] '+$line)}
function Hash([byte[]]$b){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function DownloadBytes([string]$path){Trace 'GITHUB' ('DOWNLOAD '+$path);$r=Invoke-WebRequest -Uri ($RepoBase+$path+'?cb='+[DateTime]::UtcNow.Ticks) -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop;return [Text.Encoding]::UTF8.GetBytes([string]$r.Content)}
function Valid([string]$name,[byte[]]$b){try{$t=[Text.Encoding]::UTF8.GetString($b);if($b.Length -lt 20){throw 'File is unexpectedly small.'};if($name -match '\.ps1$'){[void][scriptblock]::Create($t)}elseif($name -match '\.json$'){$null=$t|ConvertFrom-Json};return $true}catch{Trace 'VALIDATE' ('FAILED '+$name+': '+$_.Exception.Message);return $false}}
function Canonical([string]$remote){try{$b=DownloadBytes $remote;if(-not(Valid $remote $b)){throw 'Canonical validation failed.'};return $b}catch{Trace 'GITHUB' ('FAILED '+$remote+': '+$_.Exception.Message);return $null}}
function SameCanonical([string]$RemotePath,[string]$LocalPath){if(-not(Test-Path -LiteralPath $LocalPath)){return $false};try{$remote=Canonical $RemotePath;if($null -eq $remote){return $false};return ((Hash ([IO.File]::ReadAllBytes($LocalPath))) -eq (Hash $remote))}catch{return $false}}
function Https([string]$HostName){try{return [bool](Test-NetConnection -ComputerName $HostName -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded}catch{return $false}}
function Find-BraveUntrapped{$out=@();$ud=Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data';if(-not(Test-Path -LiteralPath $ud)){return @()};foreach($p in @(Get-ChildItem -LiteralPath $ud -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name -eq 'Default' -or $_.Name -like 'Profile *'})){ $ed=Join-Path $p.FullName 'Extensions';if(-not(Test-Path -LiteralPath $ed)){continue};foreach($id in @(Get-ChildItem -LiteralPath $ed -Directory -ErrorAction SilentlyContinue)){foreach($v in @(Get-ChildItem -LiteralPath $id.FullName -Directory -ErrorAction SilentlyContinue)){ $m=Join-Path $v.FullName 'manifest.json';if(Test-Path -LiteralPath $m){try{if(([string](Get-Content -LiteralPath $m -Raw|ConvertFrom-Json).name)-eq 'Untrapped'){$out+=$v.FullName}}catch{}}}}};return @($out|Sort-Object -Unique)}
function Invoke-Repair{if(-not(Test-Path -LiteralPath $SelfRepairPath)){Trace 'AUTO-REPAIR' 'self-repair.ps1 is missing.';return $false};Trace 'AUTO-REPAIR' 'Invoking bounded Untrapped self-repair.';$p=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$SelfRepairPath) -WorkingDirectory $Root -Verb RunAs -WindowStyle Normal -PassThru -ErrorAction SilentlyContinue;if($null -eq $p){Trace 'AUTO-REPAIR' 'Could not start self-repair.';return $false};$p.WaitForExit();Trace 'AUTO-REPAIR' ('Process exit code: '+$p.ExitCode);return ($p.ExitCode -eq 0)}
function RunChecks{Trace 'POLICY' 'Reading configuration, schedule and override.';$config=$null;$scheduled=$false;$override=$false;try{$config=Get-Content -LiteralPath (Join-Path $Root 'config.json') -Raw|ConvertFrom-Json;$start=[TimeSpan]::Parse([string]$config.start);$end=[TimeSpan]::Parse([string]$config.end);$now=(Get-Date).TimeOfDay;if($start -eq $end){$inWindow=$true}elseif($start -lt $end){$inWindow=($now -ge $start -and $now -lt $end)}else{$inWindow=($now -ge $start -or $now -lt $end)};$of=Join-Path $Root 'override-until.txt';if(Test-Path -LiteralPath $of){try{$until=[DateTime]::Parse((Get-Content -LiteralPath $of -Raw)).ToUniversalTime();$override=([DateTime]::UtcNow -lt $until)}catch{Problem 'Override file exists but is unreadable.'}};$scheduled=[bool]($config.enabled -and $inWindow -and -not $override);StatusLine 'Policy enabled' $config.enabled;StatusLine 'Schedule' ($config.start+' - '+$config.end);StatusLine 'Scheduled blocking' $(if($scheduled){'ACTIVE'}else{'INACTIVE'}) $(if($scheduled){'ACTIVE'}else{'INACTIVE'});StatusLine 'Override' $(if($override){'ACTIVE'}else{'INACTIVE'}) $(if($override){'ACTIVE'}else{'INACTIVE'})}catch{Problem 'Config is invalid or unreadable.';StatusLine 'Policy' 'Unable to read configuration' 'FAIL'};Trace 'POLICY' 'Testing actual target reachability.';$yt=Https 'www.youtube.com';$chat=Https 'chatgpt.com';$crush=Https 'www.crushon.ai';$expected=-not $scheduled;StatusLine 'YouTube' $(if($yt){'REACHABLE'}else{'BLOCKED'}) $(if($yt -eq $expected){'OK'}else{'MISMATCH'});StatusLine 'ChatGPT' $(if($chat){'REACHABLE'}else{'BLOCKED'}) $(if($chat -eq $expected){'OK'}else{'MISMATCH'});StatusLine 'CrushOn' $(if($crush){'REACHABLE'}else{'BLOCKED'}) $(if(-not$crush){'OK'}else{'MISMATCH'});if($yt -ne $expected){Problem 'YouTube does not match configured policy.'};if($chat -ne $expected){Problem 'ChatGPT does not match configured policy.'};if($crush){Problem 'CrushOn is reachable despite always-block policy.'};Trace 'CORE' 'Checking processes and canonical source.';$packet=@(Get-CimInstance Win32_Process|Where-Object{$_.CommandLine -like '*packet-filter.ps1*'});$control=@(Get-CimInstance Win32_Process|Where-Object{$_.CommandLine -like '*ultra-mode.ps1*'});$coreBad=@();$missing=@();foreach($f in $CoreFiles){$p=Join-Path $Root $f;if(-not(Test-Path -LiteralPath $p)){$missing+=$f}elseif(-not(SameCanonical $f $p)){$coreBad+=$f}};foreach($f in @('WinDivert.dll','WinDivert64.sys')){if(-not(Test-Path -LiteralPath (Join-Path $Root $f))){$missing+=$f}};StatusLine 'Packet filter' $(if($packet.Count){'RUNNING'}else{'STOPPED'}) $(if($packet.Count){'HEALTHY'}else{'FAIL'});StatusLine 'Control plane' $(if($control.Count){'RUNNING'}else{'STOPPED'}) $(if($control.Count){'HEALTHY'}else{'FAIL'});StatusLine 'Core source' $(if($coreBad.Count){$coreBad -join ', '}else{'CURRENT'}) $(if($coreBad.Count){'MISMATCH'}else{'OK'});StatusLine 'Required files' $(if($missing.Count){$missing -join ', '}else{'PRESENT'}) $(if($missing.Count){'FAIL'}else{'OK'});if(-not$packet.Count){Problem 'Packet filter is not running.'};if(-not$control.Count){Problem 'Control plane is not running.'};if($missing.Count){Problem ('Required Untrapped files missing: '+($missing -join ', '))};if($coreBad.Count){Problem ('Untrapped core differs from canonical GitHub: '+($coreBad -join ', '))};Trace 'EXTENSION' 'Checking Enhanced extension source.';$sourceBad=@();foreach($f in $ExtensionFiles){$p=Join-Path $Parent $f;if(-not(Test-Path -LiteralPath $p)){$sourceBad+=$f}elseif(-not(SameCanonical $f $p)){$sourceBad+=$f}};StatusLine 'Extension source' $(if($sourceBad.Count){$sourceBad -join ', '}else{'CURRENT'}) $(if($sourceBad.Count){'MISMATCH'}else{'OK'});if($sourceBad.Count){Problem ('Enhanced extension source differs from canonical GitHub: '+($sourceBad -join ', '))};Trace 'BRAVE' 'Checking installed Brave extension storage.';$installed=Find-BraveUntrapped;StatusLine 'Brave Untrapped copies' $installed.Count $(if($installed.Count){'FOUND'}else{'NOT FOUND'});if(-not$installed.Count){Problem 'Installed Brave Untrapped extension was not found in standard extension storage.'}else{foreach($d in $installed){$bad=@();foreach($f in $ExtensionFiles){if(-not(SameCanonical $f (Join-Path $d $f))){$bad+=$f}};StatusLine ('Brave copy '+$d) $(if($bad.Count){'MISMATCH'}else{'CURRENT'}) $(if($bad.Count){'MISMATCH'}else{'OK'});if($bad.Count){Problem ('Installed Brave Untrapped differs from canonical GitHub: '+($bad -join ', '))}}};Trace 'NETWORK' 'Checking Windows network stack and surrounding state.';$adapters=@(Get-NetAdapter|Where-Object{$_.Status -eq 'Up'});$routes=@(Get-NetRoute -DestinationPrefix '0.0.0.0/0');$dnsOK=$false;try{$dnsOK=@(Resolve-DnsName 'google.com' -DnsOnly -ErrorAction Stop|Where-Object{$_.IPAddress}).Count -gt 0}catch{};$google=Https 'www.google.com';$bfe=$false;try{$bfe=(Get-Service BFE).Status -eq 'Running'}catch{};$hosts=Join-Path $env:SystemRoot 'System32\drivers\etc\hosts';$hostHits=@();if(Test-Path -LiteralPath $hosts){$hostHits=@(Get-Content $hosts|Where-Object{$_ -match '(?i)(youtube|youtu\.be|chatgpt|crushon)' -and $_ -notmatch '^\s*#'})};$proxy='UNKNOWN';try{$px=netsh winhttp show proxy 2>$null;if($px -match 'Direct access'){$proxy='DIRECT'}elseif($px -match 'Proxy Server'){$proxy='CONFIGURED'}}catch{};$vpn=@(Get-NetAdapter|Where-Object{$_.Status -eq 'Up' -and $_.InterfaceDescription -match '(?i)vpn|wireguard|tun|tap|proton|speedify|warp|tailscale|openvpn'});StatusLine 'Active adapters' $adapters.Count;StatusLine 'Default routes' $routes.Count;StatusLine 'VPN/tunnel adapters' $vpn.Count;StatusLine 'DNS google.com' $(if($dnsOK){'OK'}else{'FAILED'}) $(if($dnsOK){'HEALTHY'}else{'FAIL'});StatusLine 'Google HTTPS' $(if($google){'OK'}else{'FAILED'}) $(if($google){'HEALTHY'}else{'FAIL'});StatusLine 'Relevant Hosts' $(if($hostHits.Count){$hostHits.Count}else{'CLEAR'}) $(if($hostHits.Count){'PRESENT'}else{'CLEAR'});StatusLine 'WinHTTP proxy' $proxy;StatusLine 'Base Filtering Engine' $(if($bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'}) $(if($bfe){'HEALTHY'}else{'FAIL'});if(-not$dnsOK){Problem 'External DNS resolution is failing.'};if(-not$google){Problem 'External HTTPS connectivity to Google is failing.'};if($hostHits.Count){Problem 'Relevant Hosts entries were found.'};if(-not$bfe){Problem 'Base Filtering Engine is not running.'};return @{Problems=@($Problems);Status=@($Status);Scheduled=$scheduled;Override=$override;CoreBad=@($coreBad);SourceBad=@($sourceBad);Installed=@($installed);Packet=$packet;Control=$control;Adapters=@($adapters);Routes=@($routes);Vpn=@($vpn);Dns=$dnsOK;Google=$google;Hosts=@($hostHits);Proxy=$proxy;Bfe=$bfe}}
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
Trace 'START' '=== UNTRAPPED SELF-UPDATING SYSTEM-WIDE DIAGNOSTIC ==='
Trace 'UPDATE' 'Checking diagnostic against canonical GitHub source without restarting the console.'
try{$remote=Canonical 'ultra-mode/status-untrapped.ps1';if($null -ne $remote){$local=[IO.File]::ReadAllBytes($StatusPath);if((Hash $local) -ne (Hash $remote)){Trace 'UPDATE' 'Newer diagnostic found. Backing up and replacing it.';$backup=$StatusPath+'.pre-update-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.bak';Copy-Item $StatusPath $backup -Force;$tmp=$StatusPath+'.update-'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllBytes($tmp,$remote);if((Hash ([IO.File]::ReadAllBytes($tmp))) -ne (Hash $remote)){throw 'Update verification failed.'};Move-Item $tmp $StatusPath -Force;$UpdateState='UPDATED';Trace 'UPDATE' 'Diagnostic updated successfully; continuing this process.'}else{$UpdateState='ALREADY CURRENT';Trace 'UPDATE' 'Diagnostic is already current; no update needed.'}}else{$UpdateState='UPDATE FAILED';Problem 'Could not retrieve canonical diagnostic.'}}catch{$UpdateState='UPDATE FAILED';Problem ('Diagnostic self-update failed: '+$_.Exception.Message)}
StatusLine 'Auto-update' $UpdateState $(if($UpdateState -eq 'ALREADY CURRENT' -or $UpdateState -eq 'UPDATED'){'OK'}else{'FAIL'})
$before=RunChecks
if($before.Problems.Count){Trace 'AUTO-REPAIR' ('Detected '+$before.Problems.Count+' problem(s). Starting repair.');$RepairRan=$true;Invoke-Repair|Out-Null;Trace 'AUTO-REPAIR' 'Repair process finished. Running full verification.';$after=RunChecks}else{$after=$before;Trace 'AUTO-REPAIR' 'No problems detected; repair not required.'}
$Problems=New-Object 'System.Collections.Generic.List[string]';foreach($p in $after.Problems){[void]$Problems.Add($p)}
$overall=if($Problems.Count){'UNHEALTHY'}else{'HEALTHY'}
Trace 'DIAGNOSIS' 'Building condensed, detailed and system-wide STATUS.'
$cond=@('CONDENSED DIAGNOSIS',' OVERALL: '+$overall,' Auto-update: '+$UpdateState,' Auto-repair triggered: '+$RepairRan,' Remaining problems: '+$Problems.Count);if($Problems.Count){foreach($p in $Problems){$cond+=' ! '+$p}}else{$cond+=' All checked components match the active policy and canonical source.'};$cond+='';$cond+='DETAILED DIAGNOSIS';$cond+=' Scheduled blocking active: '+$after.Scheduled;$cond+=' Override active: '+$after.Override;$cond+=' Core canonical mismatches: '+$(if($after.CoreBad.Count){$after.CoreBad -join ', '}else{'NONE'});$cond+=' Extension-source mismatches: '+$(if($after.SourceBad.Count){$after.SourceBad -join ', '}else{'NONE'});$cond+=' Installed Brave copies: '+$after.Installed.Count;$cond+=' Packet filter process: '+$(if($after.Packet.Count){'RUNNING'}else{'STOPPED'});$cond+=' Control plane process: '+$(if($after.Control.Count){'RUNNING'}else{'STOPPED'});$cond+=' Active adapters: '+$after.Adapters.Count;$cond+=' Default routes: '+$after.Routes.Count;$cond+=' VPN/tunnel adapters: '+$after.Vpn.Count;$cond+=' DNS google.com: '+$(if($after.Dns){'OK'}else{'FAILED'});$cond+=' Google HTTPS: '+$(if($after.Google){'OK'}else{'FAILED'});$cond+=' Relevant Hosts entries: '+$after.Hosts.Count;$cond+=' WinHTTP proxy: '+$after.Proxy;$cond+=' Base Filtering Engine: '+$(if($after.Bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'});$cond+='';$cond+='SYSTEM-WIDE STATUS';$cond+=' Overall: '+$overall;$cond+=' Policy: '+$(if($after.Scheduled){'SCHEDULED BLOCKING ACTIVE'}else{'SCHEDULED BLOCKING INACTIVE'});$cond+=' Override: '+$(if($after.Override){'ACTIVE'}else{'INACTIVE'});$cond+=' YouTube: '+$(if($after.Scheduled){'BLOCKED'}else{'REACHABLE'});$cond+=' ChatGPT: '+$(if($after.Scheduled){'BLOCKED'}else{'REACHABLE'});$cond+=' CrushOn: BLOCKED 24/7';$cond+=' Packet filter: '+$(if($after.Packet.Count){'HEALTHY'}else{'FAILED'});$cond+=' Control plane: '+$(if($after.Control.Count){'HEALTHY'}else{'FAILED'});$cond+=' Core source: '+$(if($after.CoreBad.Count){'MISMATCH'}else{'CURRENT'});$cond+=' Extension source: '+$(if($after.SourceBad.Count){'MISMATCH'}else{'CURRENT'});$cond+=' Brave installed copy: '+$after.Installed.Count;$cond+=' DNS: '+$(if($after.Dns){'HEALTHY'}else{'FAILED'});$cond+=' Google HTTPS: '+$(if($after.Google){'HEALTHY'}else{'FAILED'});$cond+=' Hosts: '+$(if($after.Hosts.Count){'RELEVANT ENTRIES PRESENT'}else{'CLEAR'});$cond+=' Proxy: '+$after.Proxy;$cond+=' BFE: '+$(if($after.Bfe){'HEALTHY'}else{'FAILED'});$cond+='';$cond+='DIAGNOSTIC CONTRACT';$cond+=' Only Untrapped-owned components may be changed automatically.';$cond+=' Windows Firewall/WFP/DNS/routes/Hosts/proxy/adapters/VPN/override policy are diagnostic-only.';$cond+=' Live trace records actions; status labels are reserved for meaningful health/policy outcomes.';$all=@($Lines)+@('')+$cond;$all|Set-Content -LiteralPath $ReportPath -Encoding UTF8
Write-Host '';Write-Host '================ CONDENSED DIAGNOSIS ================';$cond|ForEach-Object{Write-Host $_};Write-Host '';Write-Host '================ SYSTEM-WIDE STATUS ================';foreach($s in $Status){Write-Host $s};Write-Host '';Write-Host ('Report: '+$ReportPath)